import math

def get_order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return None

    phi = modulus - modulus // base if modulus == 2 else modulus * (1 - 1 / modulus) # This is not general for calculating phi, but let's use the order finding method

    # Calculate Euler's totient function phi(modulus)
    def euler_phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi_mod = euler_phi(modulus)

    # Find prime factors of phi_mod
    factors = set()
    d = 2
    temp_phi = phi_mod
    while d * d <= temp_phi:
        if temp_phi % d == 0:
            factors.add(d)
            while temp_phi % d == 0:
                temp_phi //= d
        d += 1
    if temp_phi > 1:
        factors.add(temp_phi)

    # Test divisors of phi_mod
    order = phi_mod
    for p in list(factors):
        current_order = order // p
        if pow(base, current_order, modulus) == 1:
            order = current_order

    return order

L = get_order(3, 10000)
